":"basic-033","name":"汶泽","source":"docs/cards/基础牌.md#basic-033","sourceText":"- 将一块区域变为水域。","sourceNotes":"地形持续、多档费用待确认。","printedCost":"1/2/3","cost":{"kind":"tiers","values":[1,2,3]},"subtype":"锦囊","tags":["神秘"],"printedRange":"全地图","type":"tactic","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4D","decisions":["terrain-overlay"]},"basic-034":{"id":"basic-034","name":"移家","source":"docs/cards/基础牌.md#basic-034","sourceText":"- 将自己移出地图，不可以被任何技能/手牌/轰炸区/毒圈选中，到下一个回合，自己选择出生地。【最高等级】","sourceNotes":"“选择出生地”的范围、回归时点、费用确定方式待确认。","printedCost":"1-6","cost":{"kind":"die","min":1,"max":6},"subtype":"锦囊","tags":["神秘"],"printedRange":"对自己使用","type":"tactic","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4D","decisions":["off-map"]},"basic-035":{"id":"basic-035","name":"约谈","source":"docs/cards/基础牌.md#basic-035","sourceText":"- 去除其身上的“化猴”效果。","sourceNotes":"恢复何种阵营、多档费用待确认。","printedCost":"2/3/4","cost":{"kind":"tiers","values":[2,3,4]},"subtype":"锦囊","tags":["神秘"],"printedRange":"全地图","type":"tactic","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4D","decisions":["faction-change"]},"basic-036":{"id":"basic-036","name":"樟脑丸","source":"docs/cards/基础牌.md#basic-036","sourceText":"- 去除其身上的“化汶”效果。","sourceNotes":"恢复何种阵营、多档费用待确认。","printedCost":"2/3/4","cost":{"kind":"tiers","values":[2,3,4]},"subtype":"锦囊","tags":["神秘"],"printedRange":"全地图","type":"tactic","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4D","decisions":["faction-change"]},"basic-037":{"id":"basic-037","name":"紫檀木","source":"docs/cards/基础牌.md#basic-037","sourceText":"- 复活一名刚死亡的角色（不超过一个回合）。","sourceNotes":"复活血量/地点、死亡窗口与费用确定方式待确认。","printedCost":"1-6","cost":{"kind":"die","min":1,"max":6},"subtype":"锦囊","tags":["神秘"],"printedRange":"全地图","type":"tactic","copies":1,"proposedCopies":1,"inherited":true,"implemented":true,"runtimeText":"复活死亡后尚未跨过一个完整个人回合结束的角色：1HP、0AP、空手，固定出生地区随机空格。d6费用按实体牌锁定至本个人回合结束，取消不重掷。","milestone":"4B","decisions":[]},"basic-038":{"id":"basic-038","name":"芦荟水","source":"docs/cards/基础牌.md#basic-038","sourceText":"- 阻止另外一个食物的效果，并且自身恢复1点血量。","sourceNotes":"响应时机待确认。","printedCost":"2","cost":{"kind":"fixed","value":2},"subtype":"食物","tags":["帝汶"],"printedRange":"全地图","type":"food","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4C","decisions":["counter-stack"]},"basic-039":{"id":"basic-039","name":"奈雪","source":"docs/cards/基础牌.md#basic-039","sourceText":"- 回复1点血量。","sourceNotes":"未发现此牌的额外文字缺项；通用规则仍见索引，不表示完整裁定已确认。","printedCost":"1","cost":{"kind":"fixed","value":1},"subtype":"食物","tags":["帝汶"],"printedRange":"对自己使用","type":"food","copies":4,"proposedCopies":4,"inherited":true,"implemented":true,"runtimeText":"自己回复1生命","milestone":"4B","decisions":[]},"basic-040":{"id":"basic-040","name":"茜帝","source":"docs/cards/基础牌.md#basic-040","sourceText":"- 所有帝汶家族恢复1点血量，西帝汶回满。","sourceNotes":"回满的生命上限按角色规则裁定。","printedCost":"2","cost":{"kind":"fixed","value":2},"subtype":"食物","tags":["帝汶"],"printedRange":"全地图","type":"food","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4B","decisions":["family-membership"]},"basic-041":{"id":"basic-041","name":"阿萨姆","source":"docs/cards/基础牌.md#basic-041","sourceText":"- 自己和队友回复一点血量。","sourceNotes":"未发现此牌的额外文字缺项；通用规则仍见索引，不表示完整裁定已确认。","printedCost":"2","cost":{"kind":"fixed","value":2},"subtype":"食物","tags":["外星"],"printedRange":"相同/相邻区域","type":"food","copies":2,"proposedCopies":2,"inherited":true,"implemented":true,"runtimeText":"自己及同区／相邻区的存活队友各回复1生命；各自为战只回复自己。","milestone":"4B","decisions":[]},"basic-042":{"id":"basic-042","name":"冰红茶","source":"docs/cards/基础牌.md#basic-042","sourceText":"- 回复1点血量。下一次“肘击”和“牢大”一样打出（不需要消耗行动点）。","sourceNotes":"“和牢大一样打出”的具体机制待确认。","printedCost":"2","cost":{"kind":"fixed","value":2},"subtype":"食物","tags":["外星"],"printedRange":"对自己使用","type":"food","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4B","decisions":["elbow-buff"]},"basic-043":{"id":"basic-043","name":"盖浇","source":"docs/cards/基础牌.md#basic-043","sourceText":"- 回复1点血量。下一次“躲避球”百分之百命中，伤害+1。【最高等级】","sourceNotes":"未发现此牌的额外文字缺项；通用规则仍见索引，不表示完整裁定已确认。","printedCost":"2","cost":{"kind":"fixed","value":2},"subtype":"食物","tags":["外星"],"printedRange":"对自己使用","type":"food","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4B","decisions":["guaranteed-hit"]},"basic-044":{"id":"basic-044","name":"农夫三拳","source":"docs/cards/基础牌.md#basic-044","sourceText":"- 回复1点血量。下次使用搏击操时不需要消耗行动点（别人对你使用也是一样）。","sourceNotes":"“别人对你使用也是一样”涉及谁免付费用待确认。","printedCost":"2","cost":{"kind":"fixed","value":2},"subtype":"食物","tags":["外星"],"printedRange":"对自身使用","type":"food","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4B","decisions":["exercise-buff"]},"basic-045":{"id":"basic-045","name":"水果","source":"docs/cards/基础牌.md#basic-045","sourceText":"- 回复1点血量+1点护盾。","sourceNotes":"护盾持续、抵扣顺序待确认。","printedCost":"2","cost":{"kind":"fixed","value":2},"subtype":"食物","tags":["外星"],"printedRange":"对自己使用","type":"food","copies":2,"proposedCopies":2,"inherited":true,"implemented":true,"runtimeText":"自己回复1生命，再获得1护盾（上限2）","milestone":"4B","decisions":[]},"basic-046":{"id":"basic-046","name":"外星人","source":"docs/cards/基础牌.md#basic-046","sourceText":"- 回复2点血量。","sourceNotes":"未发现此牌的额外文字缺项；通用规则仍见索引，不表示完整裁定已确认。","printedCost":"2","cost":{"kind":"fixed","value":2},"subtype":"食物","tags":["外星"],"printedRange":"对自己使用","type":"food","copies":2,"proposedCopies":2,"inherited":true,"implemented":true,"runtimeText":"自己回复2生命","milestone":"4B","decisions":[]},"basic-047":{"id":"basic-047","name":"营养快线","source":"docs/cards/基础牌.md#basic-047","sourceText":"- 回复1点血量，摸2张牌。","sourceNotes":"未发现此牌的额外文字缺项；通用规则仍见索引，不表示完整裁定已确认。","printedCost":"2","cost":{"kind":"fixed","value":2},"subtype":"食物","tags":["外星"],"printedRange":"对自己使用","type":"food","copies":4,"proposedCopies":4,"inherited":true,"implemented":true,"runtimeText":"自己回复1生命，再摸2张","milestone":"4B","decisions":[]},"basic-048":{"id":"basic-048","name":"油泼","source":"docs/cards/基础牌.md#basic-048","sourceText":"- 由你进行判定：1-5回满血；6扣除自己1点血量。","sourceNotes":"未发现此牌的额外文字缺项；通用规则仍见索引，不表示完整裁定已确认。","printedCost":"2","cost":{"kind":"fixed","value":2},"subtype":"食物","tags":["外星"],"printedRange":"对自己使用","type":"food","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4B","decisions":["damage-order"]},"basic-049":{"id":"basic-049","name":"帝汶斗篷","source":"docs/cards/基础牌.md#basic-049","sourceText":"- 披风：当别人使用躲避球对你生效后，你可以进行判定，若为单数，则此躲避球失效。","sourceNotes":"生效后撤销伤害的结算顺序待确认。","printedCost":"1","cost":{"kind":"fixed","value":1},"subtype":"武器（身）","tags":["帝汶"],"printedRange":"对自己使用","type":"equipment","slot":"body","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["cloak-timing"]},"basic-050":{"id":"basic-050","name":"杭高校服","source":"docs/cards/基础牌.md#basic-050","sourceText":"- 气场压迫：和你同区域的人每回合扣除一点血量（队友无效）（教学楼内无效）。","sourceNotes":"触发时点、多档装备费用待确认。","printedCost":"1/2/3","cost":{"kind":"tiers","values":[1,2,3]},"subtype":"武器（身）","tags":["神秘"],"printedRange":"对自己使用","type":"equipment","slot":"body","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["uniform-trigger"]},"basic-051":{"id":"basic-051","name":"正装","source":"docs/cards/基础牌.md#basic-051","sourceText":"- 善良高贵：你每次受到伤害都可以反伤一点（轰炸区/毒圈无效）。【特性：易碎，只可以使用3次，自动报废】","sourceNotes":"反伤目标、次数消耗和自动报废时点、多档费用待确认。","printedCost":"1/2/3","cost":{"kind":"tiers","values":[1,2,3]},"subtype":"武器（身）","tags":["神秘"],"printedRange":"对自己使用","type":"equipment","slot":"body","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["reflect-lifecycle"]},"basic-052":{"id":"basic-052","name":"粉笔","source":"docs/cards/基础牌.md#basic-052","sourceText":"- 粉尘攻击：消耗1个行动点，本次造成的伤害+1（一次攻击只能使用一次）（可以在造成伤害后使用）。\n- 落幕：你失去此装备，可以对场上任意一个人造成一点伤害。","sourceNotes":"伤害后追加时机、群体攻击加伤范围、多档装备费用待确认。","printedCost":"1/2/3","cost":{"kind":"tiers","values":[1,2,3]},"subtype":"武器（手）","tags":["神秘"],"printedRange":"对自己使用","type":"equipment","slot":"hand","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["chalk-trigger"]},"basic-053":{"id":"basic-053","name":"校医的扣分单","source":"docs/cards/基础牌.md#basic-053","sourceText":"- 心理伤害：你的攻击为真伤。","sourceNotes":"真伤与免疫/护盾关系、多档费用待确认。","printedCost":"2/3","cost":{"kind":"tiers","values":[2,3]},"subtype":"武器（手）","tags":["神秘"],"printedRange":"对自己使用","type":"equipment","slot":"hand","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["damage-order"]},"basic-054":{"id":"basic-054","name":"爆浆冰淇淋面包","source":"docs/cards/基础牌.md#basic-054","sourceText":"- 黏稠：消耗2行动点，使1名角色跳过出牌（2回合1次）。\n- 好吃：失去此装备时，你可以回复2点血量。","sourceNotes":"技能目标距离、跳过出牌范围、两回合计数待确认。","printedCost":"2","cost":{"kind":"fixed","value":2},"subtype":"武器（手）","tags":["外星"],"printedRange":"对自己使用","type":"equipment","slot":"hand","copies":2,"proposedCopies":2,"inherited":true,"implemented":true,"runtimeText":"装备于手。主动付2AP使全图一名其他角色下次个人回合不能主动出牌，仍能移动、技能和响应；自己第二次个人开始才可再用。失去时可回复2生命。","milestone":"4E","decisions":[]},"basic-055":{"id":"basic-055","name":"冰糖雪梨","source":"docs/cards/基础牌.md#basic-055","sourceText":"- 糖：对你造成伤害/被你造成伤害的角色扣除1行动点（对方没有行动点则失效）。","sourceNotes":"连续/群体伤害触发次数待确认。","printedCost":"2","cost":{"kind":"fixed","value":2},"subtype":"武器（手）","tags":["外星"],"printedRange":"对自己使用","type":"equipment","slot":"hand","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["sugar-trigger"]},"basic-056":{"id":"basic-056","name":"高宇涛","source":"docs/cards/基础牌.md#basic-056","sourceText":"- 不可阻挡：你的躲避球不是“6”就生效，且不可以“帝汶斗篷”所阻挡。","sourceNotes":"末句保留原文语法。","printedCost":"1","cost":{"kind":"fixed","value":1},"subtype":"武器（手）","tags":["外星"],"printedRange":"对自己使用","type":"equipment","slot":"hand","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["guaranteed-hit"]},"basic-057":{"id":"basic-057","name":"花露水","source":"docs/cards/基础牌.md#basic-057","sourceText":"- 字面意思：你不可以被指定为“吸血”的目标。","sourceNotes":"未发现此牌的额外文字缺项；通用规则仍见索引，不表示完整裁定已确认。","printedCost":"1","cost":{"kind":"fixed","value":1},"subtype":"武器（手）","tags":["外星"],"printedRange":"对自己使用","type":"equipment","slot":"hand","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":[]},"basic-058":{"id":"basic-058","name":"王烨超","source":"docs/cards/基础牌.md#basic-058","sourceText":"- Bling Bling：你的卡牌距离+1。","sourceNotes":"“+1”的距离单位与适用牌待确认。","printedCost":"1","cost":{"kind":"fixed","value":1},"subtype":"武器（头）","tags":["普通"],"printedRange":"对自己使用","type":"equipment","slot":"head","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["range-bonus"]},"basic-059":{"id":"basic-059","name":"眼镜","source":"docs/cards/基础牌.md#basic-059","sourceText":"- 智慧：你受伤上限为1点。\n- 武装：你失去它时可以恢复1点血量。","sourceNotes":"伤害上限适用范围、多档费用待确认。","printedCost":"1/2","cost":{"kind":"tiers","values":[1,2]},"subtype":"武器（头）","tags":["神秘"],"printedRange":"对自己使用","type":"equipment","slot":"head","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["damage-order"]},"basic-060":{"id":"basic-060","name":"手表","source":"docs/cards/基础牌.md#basic-060","sourceText":"- 回溯时间：回到上回和刚开始的位置（1回合1次）。","sourceNotes":"“上回和”为牌面原文，疑似笔误；目标回合、技能费用、多档装备费用待确认。","printedCost":"1/2","cost":{"kind":"tiers","values":[1,2]},"subtype":"武器（腕）","tags":["神秘"],"printedRange":"对自己使用","type":"equipment","slot":"wrist","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["watch-return"]},"basic-061":{"id":"basic-061","name":"植物","source":"docs/cards/基础牌.md#basic-061","sourceText":"- 致命打击：你对别人造成伤害后，可以把他传送到“云上学府”/“高唐农场”。","sourceNotes":"多档费用待确认。","printedCost":"1/2/3","cost":{"kind":"tiers","values":[1,2,3]},"subtype":"武器（腕）","tags":["神秘"],"printedRange":"对自己使用","type":"equipment","slot":"wrist","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["plant-teleport"]},"basic-062":{"id":"basic-062","name":"通哥","source":"docs/cards/基础牌.md#basic-062","sourceText":"- 停滞：被你攻击到的角色下回合不可以移动（一定要对其造成伤害）。","sourceNotes":"主动与被动移动是否都禁止待确认。","printedCost":"1","cost":{"kind":"fixed","value":1},"subtype":"武器（腕）","tags":["外星"],"printedRange":"对自己使用","type":"equipment","slot":"wrist","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["movement-suppression"]},"basic-063":{"id":"basic-063","name":"哈基米","source":"docs/cards/基础牌.md#basic-063","sourceText":"- 身躯强大：无视面包车，但是不可以下水，失去后可以传送到“山洞”。","sourceNotes":"无视范围待确认。","printedCost":"0","cost":{"kind":"fixed","value":0},"subtype":"坐骑","tags":["帝汶"],"printedRange":"对自己使用","type":"equipment","slot":"mount","copies":2,"proposedCopies":2,"inherited":true,"implemented":true,"runtimeText":"无视面包车；不能下水，失去时可传送至山洞空格。","milestone":"4E","decisions":[]},"basic-064":{"id":"basic-064","name":"面包车","source":"docs/cards/基础牌.md#basic-064","sourceText":"- 横冲直撞：停留地同行/同列的所有人扣除1点血量（队友无效），但是你不可以过水。","sourceNotes":"触发时点、频次、自身是否受影响待确认。","printedCost":"1","cost":{"kind":"fixed","value":1},"subtype":"坐骑","tags":["帝汶"],"printedRange":"对自己使用","type":"equipment","slot":"mount","copies":2,"proposedCopies":2,"inherited":false,"implemented":false,"runtimeText":null,"milestone":"4E","decisions":["van-trigger"]},"basic-065":{"id":"basic-065","name":"承汉骑","source":"docs/cards/基础牌.md#ba